			function createGrpChild() {
				var dsList = app.lookup('dsRowCnt');
				var vRowCnt = dsList.getRowCount();
			    if (vRowCnt == 0) return false;
			    var data = dsList.getRowDataRanged();
			    
			    var vaRows = ["25px"]; // 시간, 인원 항목 row 기본
			    var totalRowCnt = 0;
			    for(var i in data){
			        
			        if ((Number(data[i].TOTAL_CNT) -Number(data[i].CUR_CNT)) >= 0) {
			        	totalRowCnt += (Number(data[i].TOTAL_CNT) -Number(data[i].CUR_CNT));
			        }
			        
			    }
			    // 삽입할 데이터 로우만큼 기ow를 생성해줍니다.
			    for (var j = 0; j < totalRowCnt; j++) {
			        vaRows.push("1fr");
			    }
			    
			    var pTargetGrp = app.lookup("grpParent");
			    var parentLayout = pTargetGrp.getLayout();
			    parentLayout.setRows(vaRows);
			    parentLayout.setUseRowShade(0, true);
			    pTargetGrp.setLayout(parentLayout);
			    var pmExRows = 0;
			    var pTimeIndex = 0;
			    for(var pIndex = 0 ; pIndex < data.length ; pIndex++){
			    	var pTargetTime = data[pIndex].TIMES;
			    	var pTargetRows = 0;
			    	// 혹시나, 엑셀 업로드시 배정한 인원보다 많은 인원을 등록했을 경우 화면 Error 대비
			    	if (Number(data[pIndex].TOTAL_CNT)-Number(data[pIndex].CUR_CNT) >= 0) {
			        	pTargetRows = Number(data[pIndex].TOTAL_CNT)-Number(data[pIndex].CUR_CNT);
			    	}
			    	//createGrpChild(pmCurRows, pmTime, pmExRows, i);
			    	var index = 1;
				    var output = new cpr.controls.Output("opt"+index);
				    output.value = pTargetTime + "";
				    output.style.css({
										"font-weight" : "bold",
										"text-align" : "center"
									});

					pTargetGrp.addChild(output,{
						"colIndex": 0,
						"rowIndex": pTimeIndex+1,
						"colSpan": 1,
						"rowSpan": pTargetRows
					});
					
					while(index < (pTargetRows+1)){
					    var searchInput = new cpr.controls.SearchInput("schInput"+index+pTimeIndex);
					    searchInput.fieldLabel = "이름";
					    searchInput.id = "schInput"+index+pTimeIndex;
					    searchInput.userData("idx", index+pTimeIndex);
					    searchInput.userData("time",pTargetTime);
					   
					    
					    var inputBox = new cpr.controls.InputBox("ipb"+index+pTimeIndex);
					    inputBox.fieldLabel = "사번";
					    inputBox.id = "ipb"+index+pTimeIndex;
					    pTargetGrp.addChild(inputBox,{
					    	"colIndex": 2,
							"rowIndex": index+pTimeIndex,
							"horizontalAlign": "center",
							"verticalAlign": "center",
							"width": 200
					    });
					    
					    searchInput.userData("NameId",searchInput.id);
					    searchInput.userData("CnstId",inputBox.id);
					    searchInput.addEventListener("click", onSipb1Search);
					    searchInput.addEventListener("clear", onSipb1Clear);
					    pTargetGrp.addChild(searchInput,{
					    	"colIndex": 1,
							"rowIndex": index+pTimeIndex,
							"horizontalAlign": "center",
							"width": 200
					    });
					    
						index++;
					}
			    	
			    	pTimeIndex += pTargetRows;
			    }
			}

